// Build the 24-item judged no-GT sample: linkless paragraphs whose top retrieved
// passage scores >= theta. Stratified: authentic first, then generated by score.
import { readFileSync, writeFileSync } from "node:fs";
import { relative } from "node:path";
import { walk, stripFront, paragraphsOf } from "./jina-cache.mjs";
const VAULT = "/Users/justus/obsidian_atomized_intermediary/lab/vault";
const CACHE_PATH = process.env.JINA_CACHE || (process.env.HOME + "/.cache/srn-lab/jina-cache.json");
const PREFIX = "Document: ";
const THETA = Number(process.env.RS_THETA ?? 0.65);
const fold = (s) => s.toLowerCase().normalize("NFC").replace(/ä/g,"ae").replace(/ö/g,"oe").replace(/ü/g,"ue").replace(/ß/g,"ss").replace(/\s+/g," ").trim();
const dot = (a,b) => { let s=0; for (let i=0;i<a.length;i++) s+=a[i]*b[i]; return s; };
const l2 = (v) => { let s=0; for (const x of v) s+=x*x; s=Math.sqrt(s)||1; return v.map(x=>x/s); };
const manifest = JSON.parse(readFileSync("/Users/justus/obsidian_atomized_intermediary/lab/corpus-manifest.json","utf8"));
const INDEXABLE = new Set(manifest.answer_paths.map(p=>"real/"+p));
const AUTHENTIC = new Set(manifest.paths.map(p=>"real/"+p));
const cache = JSON.parse(readFileSync(CACHE_PATH,"utf8"));
const vec = (t) => cache[PREFIX+t] || null;
const notes = [];
for (const abs of walk(VAULT)) {
  const rel = relative(VAULT, abs);
  if (rel.startsWith("real/") && !INDEXABLE.has(rel)) continue;
  const basename = rel.replace(/\.md$/,"").split("/").pop();
  if (/\bMOC\b/i.test(basename) || /(^|\/)Attachments\//.test(rel) || /\.dup$/.test(basename)) continue;
  const body = stripFront(readFileSync(abs,"utf8"));
  notes.push({ rel, basename, body, authentic: AUTHENTIC.has(rel), paras: paragraphsOf(body) });
}
const all = notes.flatMap(n => n.paras.map(p => vec(p)).filter(Boolean));
const d = all[0].length, mean = new Array(d).fill(0);
for (const v of all) for (let i=0;i<d;i++) mean[i]+=v[i];
for (let i=0;i<d;i++) mean[i]/=all.length;
const center = (v) => l2(v.map((x,i)=>x-mean[i]));
for (const n of notes) { n.pv = n.paras.map(p=>vec(p)).filter(Boolean).map(center); }
// linkless paragraphs = raw blocks without [[..]] — approximate: paragraph text had no links
// (paragraphsOf strips links to display text; detect links from the raw body block)
const rawBlocksOf = (body) => body.replace(/```[\s\S]*?```/g,"\n").split(/\n\s*\n/);
const items = [];
for (const n of notes) {
  for (const raw of rawBlocksOf(n.body)) {
    if (/\[\[[^\]]+\]\]/.test(raw)) continue;
    const lines = raw.split("\n").filter(l=>!/^\s*#{1,6}\s/.test(l) && !/^\s*\|/.test(l)).map(l=>l.replace(/^\s*>+\s*/,"").replace(/\[![A-Za-z]+\][+-]?\s*/g,""));
    const text = lines.join(" ").replace(/^[\s>*+-]+/,"").replace(/[*_~`]/g,"").replace(/\s+/g," ").trim();
    if (text.split(/\s+/).filter(Boolean).length < 25) continue;
    const v = vec(text);
    if (!v) continue;
    const qv = center(v);
    let best=-1, bn=null, bp=null;
    for (const m of notes) {
      if (m.rel===n.rel) continue;
      for (let i=0;i<m.pv.length;i++){ const s=dot(qv,m.pv[i]); if (s>best){best=s;bn=m;bp=m.paras[i];} }
    }
    if (best >= THETA) items.push({ from:n.rel, authentic:n.authentic, score:+best.toFixed(3), to:bn.rel, para:text, passage:bp });
  }
}
items.sort((a,b)=>b.score-a.score);
const auth = items.filter(i=>i.authentic).slice(0,12);
const gen = items.filter(i=>!i.authentic).slice(0, 24-auth.length);
const sample = [...auth, ...gen];
writeFileSync("/Users/justus/obsidian_atomized_intermediary/lab/results/resurf-judging-sample.json", JSON.stringify({theta:THETA, fired:items.length, authFired:items.filter(i=>i.authentic).length, sample}, null, 1));
console.log(`fired ${items.length} linkless paragraphs at theta=${THETA} (${items.filter(i=>i.authentic).length} authentic); sample ${sample.length} (${auth.length} authentic)`);
